solution.code:
public class Main {
    public static void main(String[] args) {
        Shape s = new Square(3);
        System.out.println(s.name() + " " + s.area());
    }
}

abstract class Shape {
    abstract String name();

    abstract int area();
}

class Square extends Shape {
    private final int side;

    Square(int side) {
        this.side = side;
    }

    String name() {
        return "Square";
    }

    int area() {
        return side * side;
    }
}
